   ["13024"]={["Title"]="长者瓦尼卡", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="Your spirit burns with life, young {class}.  I accept the homage you pay, and offer in return this token...", ["Translator"]=""},
