   ["13028"]={["Title"]="灰鬃长者", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="Your spirit burns with life, young {class}.  I accept the homage you pay, and offer in return this token...", ["Translator"]=""},
   ["13029"]={["Title"]="长者帕姆亚", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="你的灵魂生气蓬勃，年轻的{class}。我接受你的致敬并回敬你这个硬币……", ["Translator"]=""},
