   ["24919"]={["Title"]="光明使者的救赎", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
   ["24922"]={["Title"]="经典旧世随机 英雄 （第一次）", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
   ["24923"]={["Title"]="燃烧的远征随机英雄 (Nth)", ["Objectives"]="", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Translator"]=""},
